package layered

import (
 "cmp"
 "slices"
)

type portBlocks struct { parent []int32; offset []int64 }
func newPortBlocks(n int) portBlocks {
 b:=portBlocks{parent:make([]int32,n),offset:make([]int64,n)}
 for i:=range b.parent {b.parent[i]=int32(i)}
 return b
}
func (b portBlocks) root(v int32)(int32,int64) {
 var offset int64
 for b.parent[v]!=v {offset+=b.offset[v];v=b.parent[v]}
 return v,offset
}
func (b portBlocks) merge(a,c int32,delta int64)bool {
 ra,pa:=b.root(a);rc,pc:=b.root(c)
 if ra==rc {return pc-pa==delta}
 difference:=delta+pa-pc
 if ra<rc {b.parent[rc],b.offset[rc]=ra,difference} else {b.parent[ra],b.offset[ra]=rc,-difference}
 return true
}
func (b portBlocks) clone()portBlocks {return portBlocks{slices.Clone(b.parent),slices.Clone(b.offset)}}
type portConstraint struct {from,to int32;distance int64}
func (b portBlocks) coordinates(p *Proper,layers [][]int32,mirror bool)([]int32,bool,error) {
 n:=len(p.Nodes)
 root,offset:=make([]int32,n),make([]int64,n)
 for i:=range root {root[i],offset[i]=b.root(int32(i))}
 params,err:=coordinateParams(p)
 if err!=nil {return nil,false,err}
 c:=coordinatePass{p:p,gap:int64(params.NodeGap)}
 constraints:=make([]portConstraint,0,n)
 for _,layer:=range layers {for i:=1;i<len(layer);i++ {
  a,d:=layer[i-1],layer[i]
  weight:=c.separation(a,d)+offset[a]-offset[d]
  from,to:=root[a],root[d]
  if from==to {if weight>0 {return nil,false,nil};continue}
  if mirror {from,to=to,from}
  constraints=append(constraints,portConstraint{from,to,weight})
 }}
 x:=make([]int64,n)
 for iteration:=0;iteration<n;iteration++ {
  changed:=false
  for _,e:=range constraints {if x[e.to]<x[e.from]+e.distance {x[e.to]=x[e.from]+e.distance;changed=true}}
  if !changed {
   out:=make([]int32,n)
   for i:=range out {value:=x[root[i]];if mirror {value=-value};out[i],err=coordinate(value+offset[i]);if err!=nil {return nil,false,err}}
   return out,true,nil
  }
 }
 return nil,false,nil
}
type portEquality struct {tail,head,decl,index int32;delta,residual int64}
func compactPortCoordinates(p *Proper,layers [][]int32,x []int32,mode int)([]int32,error) {
 if len(p.Nodes)>1000 {return x,nil}
 r:=&Routing{SourceX:make([]int32,len(p.Edges)),TargetX:make([]int32,len(p.Edges))}
 if err:=routingPorts(p,x,r);err!=nil {return nil,err}
 blocks:=newPortBlocks(len(p.Nodes))
 var choices []portEquality
 for i,e:=range p.Edges {
  if borderChain(p,e) {blocks.merge(e.Tail,e.Head,0);continue}
  if !drawChain(p,e)||p.Nodes[e.Tail].Border!=BorderNone||p.Nodes[e.Head].Border!=BorderNone {continue}
  delta:=int64(r.SourceX[i])-int64(x[e.Tail])-int64(r.TargetX[i])+int64(x[e.Head])
  choices=append(choices,portEquality{e.Tail,e.Head,e.Decl,int32(i),delta,abs64(int64(r.SourceX[i])-int64(r.TargetX[i]))})
 }
 slices.SortFunc(choices,func(a,b portEquality)int {
  order:=cmp.Or(cmp.Compare(a.residual,b.residual),cmp.Compare(a.decl,b.decl),cmp.Compare(a.index,b.index))
  if mode>=2 {order=cmp.Or(cmp.Compare(b.decl,a.decl),cmp.Compare(b.index,a.index))}
  return order
 })
 for _,e:=range choices {
  trial:=blocks.clone()
  if !trial.merge(e.tail,e.head,e.delta) {continue}
  _,feasible,err:=trial.coordinates(p,layers,false)
  if err!=nil {return nil,err}
  if feasible {blocks=trial}
 }
 out,feasible,err:=blocks.coordinates(p,layers,mode%2==1)
 if err!=nil {return nil,err}
 if !feasible {return x,nil}
 return out,nil
}

