package layered

import (
 "cmp"
 "slices"
 "github.com/gosuda/elegant-mermaid/internal/geom"
 "github.com/gosuda/elegant-mermaid/internal/scene"
)
type protectedInterval struct {lo,hi int32;leftLabel,rightLabel bool}
type coordinateCompression struct {before,after []int32}
func compactScene(original scene.Scene,titles []Box)(scene.Scene,[]Box,error) {
 x:=sceneCompression(original.Dump,titles,false)
 y:=sceneCompression(original.Dump,titles,true)
 if slices.Equal(x.before,x.after)&&slices.Equal(y.before,y.after) {return original,titles,nil}
 trial:=scene.Scene{Dump:compressedDump(original.Dump,x,y)}
 before,err:=scene.MeasureMetrics(&original.Dump,0)
 if err!=nil {return original,titles,err}
 after,err:=scene.MeasureMetrics(&trial.Dump,0)
 if err!=nil {return original,titles,err}
 improves,err:=portfolioImproves(before.SoftCost,after.SoftCost)
 if err!=nil||!improves||!after.HardOK {return original,titles,err}
 if original.Options.Profile==scene.ProfileCell&&!alignedCellClearance(trial.Dump) {return original,titles,nil}
 out:=slices.Clone(titles)
 for i:=range out {out[i].Rect=compressedRect(out[i].Rect,x,y)}
 return trial,out,nil
}
func axisSpan(r geom.Rect,vertical bool)(int32,int32) {
 if vertical {return r.Y,r.Y+r.H}
 return r.X,r.X+r.W
}
func sceneCompression(dump scene.Dump,titles []Box,vertical bool)coordinateCompression {
 points:=[]int32{0}
 var protected []protectedInterval
 for _,box:=range dump.Boxes {
  lo,hi:=axisSpan(box.Rect,vertical);points=append(points,lo,hi)
  if box.Role==scene.RoleNode {protected=append(protected,protectedInterval{lo:lo,hi:hi})}
 }
 for _,label:=range dump.Labels {lo,hi:=axisSpan(label.Rect,vertical);points=append(points,lo,hi);protected=append(protected,protectedInterval{lo,hi,true,true})}
 for _,title:=range titles {lo,hi:=axisSpan(title.Rect,vertical);points=append(points,lo,hi);protected=append(protected,protectedInterval{lo,hi,true,true})}
 for _,route:=range dump.Routes {for _,point:=range route.Points {if vertical {points=append(points,point.Y)}else{points=append(points,point.X)}}}
 if vertical {points=append(points,dump.Canvas.H)}else{points=append(points,dump.Canvas.W)}
 slices.Sort(points);points=slices.Compact(points);protected=mergeProtected(protected)
 gap:=constant(dump.Options.Profile,"node_gap")
 rankAxis:=vertical==(dump.Options.Direction!=scene.DirectionLR&&dump.Options.Direction!=scene.DirectionRL)
 if rankAxis {gap=constant(dump.Options.Profile,"rank_gap")}
 return compressCoordinates(points,protected,gap,rankAxis)
}
func mergeProtected(spans []protectedInterval)[]protectedInterval {
 slices.SortFunc(spans,func(a,b protectedInterval)int{return cmp.Or(cmp.Compare(a.lo,b.lo),cmp.Compare(a.hi,b.hi))})
 merged:=make([]protectedInterval,0,len(spans))
 for _,span:=range spans {
  if len(merged)==0||span.lo>merged[len(merged)-1].hi {merged=append(merged,span);continue}
  last:=&merged[len(merged)-1]
  if span.lo==last.lo {last.leftLabel=last.leftLabel&&span.leftLabel}
  if span.hi>last.hi {last.hi,last.rightLabel=span.hi,span.rightLabel}else if span.hi==last.hi{last.rightLabel=last.rightLabel&&span.rightLabel}
 }
 return merged
}
// Every critical coordinate remains distinct. Protected intervals translate rigidly.
func compressCoordinates(points []int32,spans []protectedInterval,gap int32,rankAxis bool)coordinateCompression {
 mapping:=coordinateCompression{before:points,after:slices.Clone(points)}
 var saved int32
 next:=0
 for i:=1;i<len(spans);i++ {
  lo,hi:=spans[i-1].hi,spans[i].lo
  for next<len(points)&&points[next]<=lo {mapping.after[next]=points[next]-saved;next++}
  end:=next
  for end<len(points)&&points[end]<hi {end++}
  minimum:=gap
  if rankAxis&&(spans[i-1].rightLabel||spans[i].leftLabel) {minimum=(gap+1)/2}
  width:=min(hi-lo,max(minimum,int32(end-next+1)))
  previous:=lo-saved
  for index:=next;index<end;index++ {
   preferred:=int32(int64(points[index]-lo)*int64(width)/int64(hi-lo))+lo-saved
   mapping.after[index]=min(max(preferred,previous+1),lo-saved+width-int32(end-index))
   previous=mapping.after[index]
  }
  saved+=hi-lo-width;next=end
 }
 for ;next<len(points);next++ {mapping.after[next]=points[next]-saved}
 return mapping
}
func(mapping coordinateCompression)value(value int32)int32 {
 index,found:=slices.BinarySearch(mapping.before,value)
 if !found {panic("layout coordinate absent from compression domain")}
 return mapping.after[index]
}
func compressedRect(r geom.Rect,x,y coordinateCompression)geom.Rect {
 x0,y0:=x.value(r.X),y.value(r.Y)
 return geom.Rect{X:x0,Y:y0,W:x.value(r.X+r.W)-x0,H:y.value(r.Y+r.H)-y0}
}
func compressedDump(original scene.Dump,x,y coordinateCompression)scene.Dump {
 dump:=original
 dump.Canvas=geom.Size{W:x.value(original.Canvas.W),H:y.value(original.Canvas.H)}
 dump.Boxes=slices.Clone(original.Boxes);dump.Labels=slices.Clone(original.Labels);dump.Routes=slices.Clone(original.Routes)
 for i:=range dump.Boxes {dump.Boxes[i].Rect=compressedRect(dump.Boxes[i].Rect,x,y)}
 for i:=range dump.Labels {dump.Labels[i].Rect=compressedRect(dump.Labels[i].Rect,x,y)}
 for i:=range dump.Routes {dump.Routes[i].Points=slices.Clone(original.Routes[i].Points);for j,p:=range dump.Routes[i].Points{dump.Routes[i].Points[j]=geom.Point{X:x.value(p.X),Y:y.value(p.Y)}}}
 return dump
}

files.internal/layout/layered/port_alignment.g:
package layered

import (
 "cmp"
 "slices"
 "github.com/gosuda/elegant-mermaid/internal/geom"
 "github.com/gosuda/elegant-mermaid/internal/scene"
)
func alignmentEligible(g *Graph)bool {return len(g.Fixed)+len(g.Attachments)+len(g.regions.sets)==0}
func alignedComponent(g *Graph,options OrderOptions)(Layout,error) {
 c,err:=orderComponent(g,options)
 if err!=nil {return Layout{},err}
 x,err:=c.regions.crossCoords(c.proper,c.order.Layers)
 if err!=nil {return Layout{},err}
 original,err:=c.placeAt(g,x)
 if err!=nil {return Layout{},err}
 for mode:=0;mode<5;mode++ {
  var aligned []int32
  if mode==0 {aligned,err=alignmentCoordinates(c.proper,c.order.Layers,x)}else{aligned,err=compactPortCoordinates(c.proper,c.order.Layers,x,mode-1)}
  if err!=nil {return Layout{},err}
  if slices.Equal(x,aligned){continue}
  trial,err:=c.placeAt(g,aligned)
  if err!=nil{return Layout{},err}
  original,err=chooseAlignment(g,original,trial)
  if err!=nil{return Layout{},err}
 }
 if forward,changed:=forwardRoutingComponent(c);changed {
  for mode:=-1;mode<5;mode++ {
   aligned:=x
   if mode==0 {aligned,err=alignmentCoordinates(forward.proper,forward.order.Layers,x)}
   if mode>0 {aligned,err=compactPortCoordinates(forward.proper,forward.order.Layers,x,mode-1)}
   if err!=nil{return Layout{},err}
   trial,err:=forward.placeAt(g,aligned)
   if err!=nil{return Layout{},err}
   for i,route:=range trial.Routes {for _,edge:=range g.Edges{if sameRoute(edge,route)&&edge.Reversed{slices.Reverse(trial.Routes[i].Points);break}}}
   original,err=chooseAlignment(g,original,trial)
   if err!=nil{return Layout{},err}
  }
 }
 return original,nil
}
func forwardRoutingComponent(c orderedComponent)(orderedComponent,bool){
 p:=*c.proper;p.Original=slices.Clone(p.Original);changed:=false
 for i:=range p.Original {e:=&p.Original[i];if !e.Reversed||e.Synthetic||e.SelfLoop(){continue};e.Tail,e.Head=e.Head,e.Tail;e.SourceGroup,e.TargetGroup=e.TargetGroup,e.SourceGroup;e.Reversed=false;changed=true}
 c.proper=&p;return c,changed
}
func chooseAlignment(g *Graph,original,trial Layout)(Layout,error){
 a,err:=softCost(g,original);if err!=nil{return Layout{},err}
 b,err:=softCost(g,trial);if err!=nil{return Layout{},err}
 improves,err:=portfolioImproves(a,b);if err!=nil||!improves{return original,err}
 valid,err:=alignedHardOK(g,trial);if err!=nil||!valid{return original,err}
 trial.BudgetExhausted=trial.BudgetExhausted||original.BudgetExhausted
 return trial,nil
}
type alignmentVote struct {delta int64;decl,index int32}
// Each semantic route votes once per gap, including parallel routes.
func alignmentCoordinates(p *Proper,layers [][]int32,x []int32)([]int32,error){
 r:=&Routing{SourceX:make([]int32,len(p.Edges)),TargetX:make([]int32,len(p.Edges))}
 if err:=routingPorts(p,x,r);err!=nil{return nil,err}
 votes:=make([][]alignmentVote,len(layers))
 for i,e:=range p.Edges{if drawChain(p,e){rank:=p.Rank[e.Tail];votes[rank]=append(votes[rank],alignmentVote{int64(r.SourceX[i])-int64(r.TargetX[i]),e.Decl,int32(i)})}}
 out:=slices.Clone(x);a:=coordinateArithmetic{};var offset int64
 for rank,layer:=range layers{
  for _,node:=range layer{value,err:=coordinate(a.add(int64(x[node]),offset));if err!=nil{return nil,err};out[node]=value}
  delta,err:=alignmentDelta(votes[rank]);if err!=nil{return nil,err};offset=a.add(offset,delta)
 }
 return out,a.err
}
type alignmentChoice struct {vote alignmentVote;count,distance int64}
func alignmentDelta(votes []alignmentVote)(int64,error){
 if len(votes)==0{return 0,nil}
 slices.SortFunc(votes,func(a,b alignmentVote)int{return cmp.Or(cmp.Compare(a.delta,b.delta),cmp.Compare(a.decl,b.decl),cmp.Compare(a.index,b.index))})
 arithmetic:=coordinateArithmetic{};var total int64
 for _,vote:=range votes{total=arithmetic.add(total,vote.delta)}
 best:=alignmentChoice{vote:alignmentVote{},count:0}
 for _,vote:=range votes{best.distance=arithmetic.add(best.distance,abs64(vote.delta))}
 var prefix int64
 for start:=0;start<len(votes);{
  end:=start+1;for end<len(votes)&&votes[end].delta==votes[start].delta{end++}
  vote:=votes[start]
  left:=arithmetic.subtract(arithmetic.multiply(vote.delta,int64(start)),prefix)
  rightSum:=arithmetic.subtract(total,prefix)
  right:=arithmetic.subtract(rightSum,arithmetic.multiply(vote.delta,int64(len(votes)-start)))
  choice:=alignmentChoice{vote,int64(end-start),arithmetic.add(left,right)}
  if alignmentBetter(choice,best){best=choice}
  prefix=arithmetic.add(prefix,arithmetic.multiply(vote.delta,int64(end-start)));start=end
 }
 return best.vote.delta,arithmetic.err
}
func alignmentBetter(a,b alignmentChoice)bool{
 return cmp.Or(cmp.Compare(b.count,a.count),cmp.Compare(a.distance,b.distance),cmp.Compare(abs64(a.vote.delta),abs64(b.vote.delta)),cmp.Compare(a.vote.decl,b.vote.decl),cmp.Compare(a.vote.index,b.vote.index),cmp.Compare(a.vote.delta,b.vote.delta))<0
}
func alignedHardOK(g *Graph,part Layout)(bool,error){
 dump,err:=alignmentDump(g,part);if err!=nil{return false,err}
 valid,err:=dump.Check()
 if err!=nil||!valid||g.LabelGutter==0{return valid,err}
 return alignedCellClearance(dump),nil
}
func alignmentDump(g *Graph,part Layout)(scene.Dump,error){
 bounds,err:=layoutBounds(part);if err!=nil{return scene.Dump{},err}
 s:=scene.Scene{Dump:scene.Dump{Options:scene.DefaultOptions(),Canvas:geom.Size{W:bounds.W,H:bounds.H}}}
 s.Options.Direction=g.Direction
 for _,box:=range part.Boxes{
  rect:=box.Rect;rect.X-=bounds.X;rect.Y-=bounds.Y
  metadata:=scene.Box{ID:box.ID,Role:box.Role,Exclusive:box.Role==scene.RoleNode}
  for _,semantic:=range g.semantic{if semantic.ID==box.ID{metadata=semantic;break}}
  metadata.Rect=rect;s.Boxes=append(s.Boxes,metadata)
 }
 for _,route:=range part.Routes{
  from,to,ok:=routeEndpoints(g,route);if !ok{return scene.Dump{},ErrGraph}
  points:=slices.Clone(route.Points);for i:=range points{points[i].X-=bounds.X;points[i].Y-=bounds.Y}
  s.Routes=append(s.Routes,scene.Route{ID:route.ID,From:from,To:to,Orthogonal:true,Points:points})
 }
 for _,box:=range part.Labels{
  rect:=box.Rect;rect.X-=bounds.X;rect.Y-=bounds.Y
  s.Labels=append(s.Labels,scene.Label{ID:box.ID,Owner:alignmentLabelOwner(g,box.ID),Rect:rect})
 }
 orientScene(&s);return s.Dump,nil
}
func alignmentLabelOwner(g *Graph,id string)string{
 for _,edge:=range g.Edges{if edge.Label==nil{continue};for _,label:=range edge.Label.Items{if label.ID==id{return edge.ID}}}
 return ""
}
func alignedCellClearance(dump scene.Dump)bool{
 for i,route:=range dump.Routes{
  for _,prior:=range dump.Routes[:i]{
   if route.From==prior.From||route.From==prior.To||route.To==prior.From||route.To==prior.To{continue}
   if alignedRoutesOverlap(route.Points,prior.Points){return false}
  }
  for j:=1;j<len(route.Points);j++{for _,label:=range dump.Labels{if alignedSegmentHitsLabel(route.Points[j-1],route.Points[j],label.Rect){return false}}}
 }
 return true
}
func alignedRoutesOverlap(p,q []geom.Point)bool{
 for i:=1;i<len(p);i++{for j:=1;j<len(q);j++{
  a,b,c,d:=p[i-1],p[i],q[j-1],q[j]
  if a==b||c==d{continue}
  if a.X==b.X&&c.X==d.X&&a.X==c.X&&max(min(a.Y,b.Y),min(c.Y,d.Y))<=min(max(a.Y,b.Y),max(c.Y,d.Y)){return true}
  if a.Y==b.Y&&c.Y==d.Y&&a.Y==c.Y&&max(min(a.X,b.X),min(c.X,d.X))<=min(max(a.X,b.X),max(c.X,d.X)){return true}
 }}
 return false
}
func alignedSegmentHitsLabel(a,b geom.Point,r geom.Rect)bool{
 if r.W==0||r.H==0||a==b{return false}
 if a.X==b.X{return a.X>=r.X&&a.X<r.X+r.W&&max(min(a.Y,b.Y),r.Y)<=min(max(a.Y,b.Y),r.Y+r.H-1)}
 return a.Y>=r.Y&&a.Y<r.Y+r.H&&max(min(a.X,b.X),r.X)<=min(max(a.X,b.X),r.X+r.W-1)
}

