package layered

import (
 "testing"
 "github.com/gosuda/elegant-mermaid/internal/geom"
 "github.com/gosuda/elegant-mermaid/internal/scene"
)
func TestPortAlignmentRemovesFanInBends(t *testing.T){
 in:=Input{Kind:"flowchart",Boxes:[]scene.Box{{ID:"n2"},{ID:"n1"},{ID:"n3"}},Text:[]string{"Untitled Node","Rounded Rectangle","Untitled Node"},Routes:[]scene.Route{{ID:"e0",From:"n2",To:"n1",Orthogonal:true},{ID:"e1",From:"n3",To:"n1",Orthogonal:true}}}
 options:=scene.DefaultOptions();options.Direction=scene.DirectionBT
 s,err:=LayoutFamily(in,Options{Scene:options});if err!=nil{t.Fatal(err)}
 metrics,err:=scene.MeasureMetrics(&s.Dump,0);if err!=nil{t.Fatal(err)}
 if !metrics.HardOK||metrics.Crossings!=0||metrics.Bends!=2||metrics.SoftCost>7{t.Fatalf("fixed-port fan-in must keep hard constraints with two bends and cost at most seven: %+v",metrics)}
}
func TestWideFanoutKeepsEveryRouteStraight(t *testing.T){
 in:=Input{Kind:"flowchart",Boxes:[]scene.Box{{ID:"P"},{ID:"A"},{ID:"B"},{ID:"C"}},Text:[]string{"Parent with enough width for three separate ports","A","B","C"},Sizes:[]geom.Size{{W:20000,H:3584}},Routes:[]scene.Route{{ID:"e0",From:"P",To:"A",Orthogonal:true},{ID:"e1",From:"P",To:"B",Orthogonal:true},{ID:"e2",From:"P",To:"C",Orthogonal:true}}}
 s,err:=LayoutFamily(in,Options{Scene:scene.DefaultOptions()});if err!=nil{t.Fatal(err)}
 m,err:=scene.MeasureMetrics(&s.Dump,0);if err!=nil{t.Fatal(err)}
 if !m.HardOK||m.Crossings!=0||m.Bends!=0{t.Fatalf("wide fan-out has room for three straight routes: %+v",m)}
}
func TestFeedbackRouteUsesItsClearRankChannel(t *testing.T){
 in:=Input{Kind:"flowchart",Boxes:[]scene.Box{{ID:"A"},{ID:"B"}},Text:[]string{"A","B"},Routes:[]scene.Route{{ID:"e0",From:"A",To:"B",Orthogonal:true},{ID:"e1",From:"B",To:"A",Orthogonal:true}}}
 s,err:=LayoutFamily(in,Options{Scene:scene.DefaultOptions()});if err!=nil{t.Fatal(err)}
 m,err:=scene.MeasureMetrics(&s.Dump,0);if err!=nil{t.Fatal(err)}
 if !m.HardOK||m.Crossings!=0||m.Bends!=0||m.AgainstFlowEdges!=1||len(s.Routes)!=2{t.Fatalf("feedback chain must preserve both directed routes without a surrounding lane: %+v",m)}
}

